15	)
16	
17	// This descriptor is resolved for each operation, never persisted. Graph owns
18	// the filename, schema, cache identity and lifecycle. Brain opens only its
19	// versioned views, read-only; no graph rows are copied into Brain storage.
20	type graphStoreDescriptor struct {
21		BrainDir         string         `json:"brain_dir,omitempty"`
22		ContractVersion  int            `json:"contract_version"`
23		Path             string         `json:"path"`
24		EntryDigest      string         `json:"entry_digest"`
25		Commit           string         `json:"commit"`
26		Tree             string         `json:"tree"`
27		Header           semanticHeader `json:"header"`
28		Files            int            `json:"files"`
29		Symbols          int            `json:"symbols"`
30		Relations        int            `json:"relations"`
31		Externals        int            `json:"externals"`
32		StoreUnavailable bool           `json:"store_unavailable"`
33		Detail           string         `json:"detail"`
34	}
35	
36	const graphStoreHandlePrefix = "graph-store-v1:"
37	
38	func fetchGraphStore(ctx context.Context, opts Options, repoDir, binary, profile string) (graphStoreDescriptor, error) {
39		if ctx == nil {
40			ctx = context.Background()
41		}
42		if binary == "" {
43			binary = "entire"
44		}
45		if profile == "" {
46			profile = "full"
47		}
48		args := []string{"graph", "store", "--repo", repoDir, "--profile", profile}
49		ignores, err := semanticProviderIgnoreFiles(repoDir)
50		if err != nil {
51			return graphStoreDescriptor{}, err
52		}
53		for _, ignore := range ignores {
54			args = append(args, "--ignore-file", ignore)
55		}
56		ctx, cancel := context.WithTimeout(ctx, graphTaskContextTimeout)
57		defer cancel()
58		stdout, stderr, err := opts.Runner.Run(ctx, repoDir, binary, args...)
59		if err != nil {
60			detail := strings.ToLower(string(stderr) + string(stdout))
61			if strings.Contains(detail, "unknown command") || strings.Contains(detail, "unknown subcommand") {
62				return graphStoreDescriptor{}, errGraphStoreUnsupported
63			}
64			return graphStoreDescriptor{}, fmt.Errorf("Graph read-only store unavailable: %w: %s", err, firstLine(strings.TrimSpace(string(stderr))))
65		}
66		var d graphStoreDescriptor
67		if err := json.Unmarshal(stdout, &d); err != nil {
68			return d, fmt.Errorf("decode Graph store descriptor: %w", err)
69		}
70		if d.StoreUnavailable {
71			return d, fmt.Errorf("%w: %s; run %s", errGraphStoreUnavailable, d.Detail, brainInvocation(os.LookupEnv, "refresh index"))
72		}
73		// A contract mismatch names the binary that is behind: a NEWER contract than
74		// this build supports means Graph has moved on and entire-brain must catch
75		// up; an OLDER contract means the installed Graph predates the interface
76		// brain needs, so Graph is the one to upgrade. Both are a present, responding
77		// Graph reporting an incompatible version -- distinct from errGraphStoreUnsupported,
78		// which means Graph never answered the store command at all (effectively
79		// absent) and is handled separately above.
80		if d.ContractVersion > graphStoreSupportedContract {
81			return d, fmt.Errorf("%w (Graph reports store contract %d, this build supports %d)", errGraphStoreContractNewer, d.ContractVersion, graphStoreSupportedContract)
82		}
83		if d.ContractVersion != graphStoreSupportedContract {
84			return d, fmt.Errorf("%w (Graph reports store contract %d, this build requires %d)", errGraphStoreContractOlder, d.ContractVersion, graphStoreSupportedContract)
85		}
86		if err := validateSemanticSchema(d.Header.SchemaVersion); err != nil {
87			// validateSemanticSchema's own text names what this build reads but not
88			// who's asking; naming both Graph (the header's source) and entire-brain
89			// (what rejected it) here matches the other version-mismatch messages in
90			// this file.
91			return d, fmt.Errorf("Graph's semantic schema is unsupported by this entire-brain build: %w", err)
92		}
93		if !filepath.IsAbs(d.Path) || d.EntryDigest == "" || d.Commit == "" || d.Tree == "" {
94			return d, errors.New("Graph returned an unsupported or incomplete store descriptor")
95		}
96		return d, nil
97	}
98	
99	// graphStoreSupportedContract is the one read-only store contract this build
100	// speaks. It is independent of semanticSchemaVersion: the contract is the
101	// shape of graphStoreDescriptor and its SQLite views, while the schema is the
102	// data model inside them (ADR 0001).
103	const graphStoreSupportedContract = 1
104	
105	var errGraphStoreUnsupported = fmt.Errorf("installed Graph lacks the read-only store interface; upgrade Graph to enable code inspection (requires store contract %d)", graphStoreSupportedContract)
106	
107	// errGraphStoreContractNewer flags a store built by a Graph that has already
108	// moved past the contract this build understands. The fix is the other
109	// direction from errGraphStoreUnsupported: upgrade entire-brain, not Graph.
110	var errGraphStoreContractNewer = errors.New("Graph's read-only store contract is newer than this build of entire-brain supports; upgrade entire-brain")
111	
112	// errGraphStoreContractOlder flags an installed Graph that DOES answer the
113	// store command but reports a contract version older than this build
114	// requires -- a present, responding Graph with an incompatible version. This
115	// is deliberately a different sentinel from errGraphStoreUnsupported (the
116	// command didn't exist at all, i.e. Graph is effectively absent): status
117	// treats "absent" as the ordinary, silent case and must not collapse this
118	// actionable version mismatch into the same bucket.
119	var errGraphStoreContractOlder = errors.New("Graph's read-only store contract is older than this build of entire-brain requires; upgrade Graph")
120	
121	var errGraphStoreUnavailable = errors.New("Graph store unavailable")
122	
123	func graphStoreSource(d graphStoreDescriptor, brainDir string) *semanticSourceManifest {
124		d.BrainDir = brainDir
125		encoded, _ := json.Marshal(struct {
126			Path        string `json:"path"`
127			EntryDigest string `json:"entry_digest"`
128			BrainDir    string `json:"brain_dir"`
129		}{d.Path, d.EntryDigest, brainDir})
130		h := d.Header
131		// fetchGraphStore already refused a schema this build cannot read at all
132		// (ADR 0001's major boundary); a newer supported-major minor still reaches
133		// here and must be recorded as a warning before SchemaVersion is copied, so
134		// the persisted source does not silently claim full ingestion.
135		warnings := append(append([]semanticWarning(nil), h.Warnings...), semanticSchemaWarnings(h.SchemaVersion)...)
136		return &semanticSourceManifest{Provider: "entire-graph", ProviderVersion: h.ProviderVersion, IdentityRevision: h.IdentityRevision, SchemaVersion: h.SchemaVersion, Commit: d.Commit, Tree: d.Tree, Profile: h.Profile, Symbols: d.Symbols, Relations: d.Relations, Externals: d.Externals, Files: d.Files, NoEgressVerified: true, StoreOwner: "graph", StorePath: graphStoreHandlePrefix + base64.RawURLEncoding.EncodeToString(encoded), graphStore: &d, Languages: h.Languages, LanguageTiers: h.LanguageTiers, Capabilities: h.Capabilities, Warnings: warnings, PartialFailures: h.PartialFailures, Completeness: h.Completeness, Stats: h.Stats, ProfileLimits: h.ProfileLimits, RelationSet: h.RelationSet, CompletenessLevel: completenessLevelFromStats(h.Stats), Trust: trustForCompleteness(completenessLevelFromStats(h.Stats))}
137	}
138	
139	// semanticSchemaWarnings returns the minor-skew warning for a live Graph store
140	// header, or nil. validateSemanticSchema's hard major refusal already ran in
141	// fetchGraphStore before any caller reaches this point, so only the
142	// non-fatal, supported-major case remains to check here.
143	func semanticSchemaWarnings(schemaVersion string) []semanticWarning {
144		if skew := semanticSchemaMinorSkewWarning(schemaVersion); skew != nil {
145			return []semanticWarning{*skew}
146		}
147		return nil
148	}
149	
150	func loadGraphManifest(ctx context.Context, opts Options, repoDir, brainDir string) (*exportManifest, error) {
151		manifest, err := loadBrainManifest(brainDir)
152		if err != nil {
153			return nil, err
154		}
155		if manifest.Sources == nil {
156			manifest.Sources = &brainSources{}
157		}
158		profile := graphStoreProfile(manifest)
159		d, err := fetchGraphStore(ctx, opts, repoDir, "", profile)
160		if err != nil {
161			return nil, err
162		}
163		manifest.Sources.Semantic = graphStoreSource(d, brainDir)
164		return manifest, nil
165	}
166	
167	func graphStoreProfile(manifest *exportManifest) string {
168		if manifest != nil && manifest.Sources != nil && manifest.Sources.Semantic != nil && manifest.Sources.Semantic.Profile != "" {
169			return manifest.Sources.Semantic.Profile
170		}
171		return "full"
172	}
173	
174	// openSemanticReadDB opens the provider's versioned projection. TEMP VIEWs
175	// are connection-local aliases, not a second store. A single connection keeps
176	// those aliases visible throughout the operation. mode=ro protects Graph even
177	// if a future caller accidentally attempts a write.
178	func openSemanticReadDB(handle string) (*sql.DB, error) {
179		if !strings.HasPrefix(handle, graphStoreHandlePrefix) {
180			return sql.Open(sqliteDriverName, sqliteReadOnlyDSN(handle))
181		}
182		raw, err := base64.RawURLEncoding.DecodeString(strings.TrimPrefix(handle, graphStoreHandlePrefix))
183		if err != nil {
184			return nil, err
185		}
186		var d graphStoreDescriptor
187		if err = json.Unmarshal(raw, &d); err != nil {
188			return nil, err
189		}
190		db, err := sql.Open(sqliteDriverName, sqliteReadOnlyDSN(d.Path))
191		if err != nil {
192			return nil, err
193		}
194		db.SetMaxOpenConns(1)
195		fail := func(err error) (*sql.DB, error) { db.Close(); return nil, err }
196		var digest string
197		if err = db.QueryRow("SELECT value FROM meta WHERE key='entry_digest'").Scan(&digest); err != nil {
198			return fail(err)
199		}
200		var actual string
201		if err = json.Unmarshal([]byte(digest), &actual); err != nil || actual != d.EntryDigest {
202			return fail(errors.New("Graph store changed after resolution; retry the operation"))
203		}
204		for _, table := range []string{"symbols", "relations", "files", "reverse_relations", "symbol_fts"} {
205			brainView := "brain_" + table + "_v1"
206			if _, err = db.Exec("CREATE TEMP VIEW " + table + " AS SELECT * FROM main." + brainView); err != nil {
207				return fail(graphStoreViewMismatchError(brainView, err))
208			}
209			// SQLite does not resolve a view's SELECT until it is actually used, so
210			// CREATE TEMP VIEW above succeeds even when brainView no longer exists.
211			// table_info forces that resolution now, zero rows, so a provider that
212			// renamed or dropped a view fails right here with a named error instead
213			// of a raw "no such table" from whatever caller happens to query it
214			// first.
215			if _, err = db.Exec("PRAGMA table_info(" + table + ")"); err != nil {
216				return fail(graphStoreViewMismatchError(brainView, err))
217			}
218		}
219		if err = loadGraphTraceTable(db, d.BrainDir); err != nil {
220			return fail(err)
221		}
222		return db, nil
223	}
224	
225	// graphStoreViewMismatchError names both binaries: either direction can rename
226	// or drop a brain_*_v1 view, so a raw sqlite "no such table" does not say
227	// which one is wrong. The cause is only wrapped, not inspected -- a schema
228	// mismatch is the likely reason but not the only one a view can fail to
229	// resolve (a corrupted or concurrently-locked store can too), so the message
230	// hedges between both remedies instead of asserting a diagnosis it can't verify.
231	func graphStoreViewMismatchError(brainView string, cause error) error {
232		return fmt.Errorf("Graph store view %s could not be resolved: %w (upgrade entire-brain or Graph to matching versions if this is a schema mismatch, or refresh the index if the store is corrupted)", brainView, cause)
233	}
234	
235	func runGraphOwnedIndex(ctx context.Context, cmd *cobra.Command, opts Options, indexOpts semanticIndexOptions, target string) error {
236		if ctx == nil {
237			ctx = context.Background()
238		}
239		if indexOpts.worktree {
240			return errors.New("Graph owns the committed-tree index; use entire graph query without --head to inspect uncommitted code")
241		}
242		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
243		if err != nil {
244			return err
245		}
246		if !local {
247			return fmt.Errorf("index requires a local repository: %s", target)
248		}
249		if err = enforceIndexContainment(indexOpts.containRoot, repoDir); err != nil {
250			return err
251		}
252		if _, err := gitScalar(ctx, opts.Runner, repoDir, "rev-parse", "HEAD"); err != nil {
253			return nameDegenerateRepoFailure(ctx, opts.Runner, repoDir, fmt.Errorf("resolve HEAD for Graph index: %w", err))
254		}
255		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
256		if err != nil {
257			return err
258		}
259		if indexOpts.outputExplicit {
260			storage.BrainDir, err = filepath.Abs(indexOpts.outputDir)
261			if err != nil {
262				return err
263			}
264		}
265		// Retire the duplicate even on installations without Graph. Authored
266		// observations are durable; code indexes are reproducible provider data.
267		if err := migrateBrainGraphStorage(storage.BrainDir, storage.Key); err != nil {
268			return err
269		}
270		binary := indexOpts.graphBinary
271		if binary == "" {
272			binary = indexOpts.semBinary
273		}
274		if binary == "" {
275			binary = "entire"
276		}
277		if indexOpts.skipGraph || indexOpts.skipSem {
278			return semanticProviderAbsentError{err: errors.New("Graph was explicitly disabled")}
279		}
280		doctor, warnings := runSemanticDoctor(ctx, opts.Runner, repoDir, binary)
281		if !doctor.NoEgress {
282			return semanticDoctorFailureError(binary, warnings)
283		}
284		profile := indexOpts.profile
285		if profile == "" {
286			profile = "full"
287		}
288		args := []string{"graph", "index", "--repo", repoDir, "--head", "--profile", profile, "--format", "json"}
289		if indexOpts.force {
290			args = append(args, "--force")
291		}
292		ignores, err := semanticProviderIgnoreFiles(repoDir)
293		if err != nil {
294			return err
295		}
296		for _, ignore := range ignores {
297			args = append(args, "--ignore-file", ignore)
298		}
299		runner, ok := opts.Runner.(EnvironmentCommandRunner)
300		if !ok {
301			return errors.New("Graph indexing requires a runner supporting per-command environment")
302		}
303		// Fail fast with the clear, specific message instead of letting an
304		// incompatible Graph run the real index command and surface a muddier
305		// binary-sourced error. Covers both directions reported by an installed
306		// Graph that actually answered (errGraphStoreContractOlder) and the case
307		// where it didn't answer at all (errGraphStoreUnsupported, Graph absent).
308		// errGraphStoreContractNewer is deliberately not fail-fasted here: Graph
309		// is ahead, not broken, and the real index command is Graph's own concern.
310		if _, probeErr := fetchGraphStore(ctx, opts, repoDir, binary, profile); errors.Is(probeErr, errGraphStoreUnsupported) || errors.Is(probeErr, errGraphStoreContractOlder) {
311			return probeErr
312		}
313		timeout := indexOpts.timeout
314		if timeout <= 0 {
315			timeout = semanticSnapshotTimeout
316		}
317		ctx, cancel := context.WithTimeout(ctx, timeout)
318		defer cancel()
319		indexOpts.reportPhase("building Graph-owned store")
320		stdout, stderr, err := runner.RunWithEnv(ctx, repoDir, map[string]string{"ENTIRE_GRAPH_SEARCH_STORE": "1"}, binary, args...)
321		if err != nil {
322			return fmt.Errorf("Graph index: %w: %s", err, firstLine(strings.TrimSpace(string(stderr))))
323		}
324		d, err := fetchGraphStore(ctx, opts, repoDir, binary, profile)
325		if err != nil {
326			return err
327		}
328		unlock, err := acquireSemanticIndexLock(storage.BrainDir)
329		if err != nil {
330			return err
331		}
332		defer unlock()
333		// Preserve authored traces before removing any legacy graph artifacts.
334		if err = migrateLegacyGraphTraces(storage.BrainDir); err != nil {
335			return err
336		}
337		source := graphStoreSource(d, storage.BrainDir)
338		source.StorePath = ""
339		source.GeneratedAt = opts.Now().UTC()
