// and brain_status. Other read surfaces retain strict artifact validation.
func buildAvailableBrainStatusReport(ctx context.Context, opts Options, target string) (brainStatusReport, error) {
	return buildBrainStatusReportWithAvailability(ctx, opts, target, true)
}

func buildBrainStatusReportWithAvailability(ctx context.Context, opts Options, target string, lightweight bool) (brainStatusReport, error) {
	repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
	if err != nil {
		return brainStatusReport{}, err
	}
	if !local {
		return brainStatusReport{}, fmt.Errorf("status requires a local repository path: %s", target)
	}
	storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
	if err != nil {
		return brainStatusReport{}, err
	}
	generatedAt := opts.Now().UTC()
	manifestState := "current"
	manifestSchema := brainManifestSchemaVersion
	var manifest *exportManifest
	var healthIssues []memoryHealthIssue
	if lightweight {
		var health memoryManifestHealth
		var issue *memoryHealthIssue
		manifest, health, issue = inspectBrainManifestHealth(storage.BrainDir)
		manifestState = health.State
		manifestSchema = health.SchemaVersion
		if issue != nil {
			healthIssues = append(healthIssues, *issue)
		}
	} else {
		manifest, err = loadBrainManifest(storage.BrainDir)
		if err != nil {
			return brainStatusReport{}, err
		}
		manifestSchema = manifest.SchemaVersion
	}
	// Legacy graph artifacts are not consulted by status or brief. Graph is
	// optional: retain all non-code Brain sources when it is absent, and "not
	// installed" / "not indexed yet" stay silent here exactly as before (they
	// already surface through the missing-semantic-index messaging below). A
	// store that Graph IS able to describe but that this build cannot actually
	// use -- a version mismatch, a corrupt descriptor, a command that failed
	// outright -- is a different, actionable problem, and used to vanish along
	// with the ordinary case. That one is recorded as a warning instead.
	var graphStatusWarning string
	if manifest != nil {
		if manifest.Sources == nil {
			manifest.Sources = &brainSources{}
		}
		profile := graphStoreProfile(manifest)
		manifest.Sources.Semantic = nil
		if d, graphErr := fetchGraphStore(ctx, opts, repoDir, "", profile); graphErr != nil {
			if !errors.Is(graphErr, errGraphStoreUnsupported) && !errors.Is(graphErr, errGraphStoreUnavailable) {
				graphStatusWarning = "graph store unavailable: " + graphErr.Error()
			}
		} else {
			manifest.Sources.Semantic = graphStoreSource(d, storage.BrainDir)
		}
	}
	report := brainStatusReport{
		GeneratedAt: generatedAt,
		Repo:        brainStatusRepo{Root: repoDir, Key: storage.Key},
		Brain: brainStatusBrain{
			Path:            storage.BrainDir,
			Schema:          manifestSchema,
			SupportedSchema: brainManifestSchemaVersion,
			ManifestState:   manifestState,
		},
		Manifest: manifest,
		Issues:   healthIssues,
	}
	if graphStatusWarning != "" {
		report.Warnings = append(report.Warnings, graphStatusWarning)
	}
	if lightweight {
		report.Integrity = "not_checked"
	}
	if manifest != nil && !manifest.GeneratedAt.IsZero() {
		report.Brain.GeneratedAt = manifest.GeneratedAt.Format(time.RFC3339)
	}
	if manifest != nil && manifest.Sources != nil {
		report.Sources.Seed = manifest.Sources.Seed != nil

	// maxManifestBytes bounds auxiliary JSON state/index/cursor files.
	// Canonical Brain manifests use the dedicated, uncapped manifest reader.
	maxManifestBytes int64 = 16 << 20 // 16 MiB
)

const (
	// maxSeedDocBytes bounds a single seed/markdown document read for chunking.
	maxSeedDocBytes = 32 << 20 // 32 MiB

	// defaultMaxSemanticSnapshotBytes bounds a full entire-graph snapshot read. It is
	// generous because a large monorepo's snapshot is legitimately big; operators
	// with even larger repos can raise it via ENTIRE_BRAIN_MAX_SNAPSHOT_BYTES.
	defaultMaxSemanticSnapshotBytes = 2 << 30 // 2 GiB
)

// semanticSnapshotMaxBytes returns the ceiling for reading a full semantic
// snapshot, honoring an ENTIRE_BRAIN_MAX_SNAPSHOT_BYTES override so unusually
// large repositories are not artificially blocked.
func semanticSnapshotMaxBytes() int64 {
	if v := os.Getenv("ENTIRE_BRAIN_MAX_SNAPSHOT_BYTES"); v != "" {
		if n, err := strconv.ParseInt(v, 10, 64); err == nil && n > 0 {
			return n
		}
	}
	return defaultMaxSemanticSnapshotBytes
}

